  /* ============ Integrações 04 — Pixel como fonte do catálogo (Catálogo › Fontes de dados › Adicionar › Pixel) ============ */
  function catId() { try { var c = JSON.parse(localStorage.getItem('sim.catalogo') || 'null'); return c && c.cats && c.cats[0] ? c.cats[0].id : (window.SIMCM ? SIMCM.exemplo() : '') } catch (e) { return window.SIMCM ? SIMCM.exemplo() : '' } }
  function preparaCatPx() {   // começa do zero: sem eventos, sem verificação de microdados, sem fonte Pixel; o Pixel (conjunto de dados) existe
    try {
      localStorage.setItem('sim.feed', '[]'); localStorage.removeItem('sim.microdados');
      var ev = JSON.parse(localStorage.getItem('sim.eventos') || 'null') || { datasets: [], testeDesde: 0 };
      if (!ev.datasets || !ev.datasets.length) { ev.datasets = [{ id: '1779103133372149', nome: 'Pixel da Mari', criado: Date.now(), capi: false, am: true, cookies: true, auto: false }]; localStorage.setItem('sim.eventos', JSON.stringify(ev)) }
      if (window.SIMCM) { SIMCM.exemplo(); var s = SIMCM.estado().S; s.cats[0].fontes = s.cats[0].fontes.filter(function (x) { return x.tipo !== 'Pixel' }); localStorage.setItem('sim.catalogo', JSON.stringify(s)) }
    } catch (e) { }
  }
